<?php
require_once __DIR__.'/config.php'; require_auth(); require_permission('view_vehicle_history'); $pdo=db();$u=current_user();$vid=(int)($_GET['vehicle_id']??0);$st=$pdo->prepare("SELECT v.*,c.full_name FROM vehicles v JOIN customers c ON c.id=v.customer_id WHERE v.id=:v");$st->execute([':v'=>$vid]);$v=$st->fetch();if(!$v)die('السيارة غير موجودة.');if($u['role']==='customer'){$st=$pdo->prepare("SELECT id FROM customers WHERE user_id=:u");$st->execute([':u'=>$u['id']]);if((int)$st->fetchColumn()!==(int)$v['customer_id'])die('غير مصرح لك.');}$st=$pdo->prepare("SELECT wo.*,s.name service_name,i.invoice_number,i.total_amount,i.paid_amount FROM work_orders wo LEFT JOIN services s ON s.id=wo.service_id LEFT JOIN invoices i ON i.work_order_id=wo.id WHERE wo.vehicle_id=:v ORDER BY wo.created_at DESC");$st->execute([':v'=>$vid]);$rows=$st->fetchAll();?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>سجل السيارة</title><link rel="stylesheet" href="style.css"></head><body class="dashboard-body"><div class="dashboard-wrapper"><main class="main-content" style="width:100%"><header class="topbar"><h2 class="page-title">🚗 سجل صيانة السيارة</h2><a class="btn btn-outline" href="vehicles.php">العودة</a></header><div class="content-container"><div class="card mb-4"><div class="card-body"><h3><?=clean($v['make'].' '.$v['model'])?></h3><p>اللوحة: <?=clean($v['plate_number'])?> — العميل: <?=clean($v['full_name'])?></p></div></div><div class="card"><div class="card-body" style="overflow-x:auto"><table class="data-table"><thead><tr><th>أمر الصيانة</th><th>الخدمة</th><th>الحالة</th><th>التكلفة</th><th>الفاتورة</th><th>التاريخ</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=clean($r['order_number'])?></td><td><?=clean($r['service_name']??'-')?></td><td><?=status_badge($r['status'])?></td><td><?=format_money($r['actual_cost'])?></td><td><?=clean($r['invoice_number']??'-')?><?=isset($r['total_amount'])?' — '.format_money($r['total_amount']):''?></td><td><?=clean($r['created_at'])?></td></tr><?php endforeach;?></tbody></table></div></div></div></main></div></body></html>